import { Fragment, type ReactNode } from 'react'
import { SiteHeader } from '@/components/site/SiteHeader'
import { SiteFooter } from '@/components/site/SiteFooter'
import { TeamList } from '@/components/site/TeamList'
import { ProcessList } from '@/components/site/ProcessList'
import { Openings } from '@/components/site/Openings'
import { aboutContent, aboutSections, type AboutContent, type AboutSection } from '@/lib/pages/about'
import { pageSections } from '@/lib/image'
import { cn } from '@/lib/cn'

// The about page from library items (components/about-view.tsx): the bets centered at the display step (the title
// and the closing line in white, the bets in mid, a blank line between), the team's names, the process (its statement
// in two tones over the numbered rows) and the openings. `content` replaces the copy (lib/pages/about.ts).
export interface AboutPageProps {
  content?: AboutContent
  sections?: readonly AboutSection[]
  className?: string
}

export function AboutPage({ content: c = aboutContent, sections, className }: AboutPageProps) {
  const parts: Record<AboutSection, ReactNode> = {
    bets: (
      <section aria-labelledby="bets-heading" className="px-6 pt-32 pb-24 text-center sm:pt-44">
        <h1 id="bets-heading" className="type-section text-fg">{c.bets.title}</h1>
        <div className="mx-auto mt-10 flex max-w-(--ds-layout-page) flex-col gap-10 type-section text-balance">
          {c.bets.lines.map((l) => <p key={l} className="text-fg-muted">{l}</p>)}
          <p className="text-fg">{c.bets.close}</p>
        </div>
      </section>
    ),
    team: <section aria-label="Team" className="py-24"><TeamList members={c.team} /></section>,
    process: (
      <section aria-labelledby="process-heading" className="px-6 py-14">
        <h2 id="process-heading" className="max-w-(--ds-layout-page) type-section"><span className="text-fg">{c.process.lead}</span> <span className="text-fg">{c.process.rest}</span></h2>
        <ProcessList steps={c.process.steps} className="mt-12" />
      </section>
    ),
    openings: <Openings roles={c.roles} />,
  }
  return (
    <div data-ds="about-page" className={cn('flex min-h-screen w-full flex-col bg-surface text-fg', className)}>
      <SiteHeader {...c.header} links={c.header.links.map((l) => ({ ...l, current: l.href === '/about' }))} />
      <main className="flex-1">{pageSections(aboutSections, sections).map((k) => <Fragment key={k}>{parts[k]}</Fragment>)}</main>
      <SiteFooter links={c.footer.links} />
    </div>
  )
}

export default AboutPage

import { footer, header } from '@/lib/pages/chrome'
// The about page template's copy (components/about-view.tsx): the bets, the team, the process and the openings. The
// bets and the process are the studio's own words; the team and the roles are Acme's.
export const aboutContent = {
	header,
	bets: {
		title: 'Our bets:',
		lines: [
			"Companies don't want designers to implement styles or design. They'd much rather use AI to do it themselves, faster and cheaper.",
			'The job of designers will become almost completely about design thinking. AI will handle almost all execution, and designers will solve problems and come up with ideas.',
			'Products and websites need to be geared for agent usage. Agents will become major users of websites and products themselves.',
		],
		close: 'This is why we build design systems for both teams and LLMs.',
	},
	team: [
		{ name: 'Alex Rivera', role: 'Founder', location: 'London' },
		{ name: 'Sam Lee', role: 'Design', location: 'Lagos' },
		{ name: 'Jordan Park', role: 'Engineering', location: 'Berlin' },
		{ name: 'Casey Morgan', role: 'Design', location: 'Manila' },
		{ name: 'Riley Chen', role: 'Engineering', location: 'Cairo' },
	],
	process: {
		lead: 'Harnessing an AI-first approach to accelerate our craft.',
		rest: "Our agentic design and engineering process keeps us at the forefront of what's possible.",
		steps: [
			{ title: 'Exploration is fast. Judgement is not.', body: 'We explore design variants in code first, then refine and polish them in Figma, not the other way around.' },
			{ title: 'Speed requires agility.', body: 'Working faster increases the need for a clear process. Ours is structured yet agile and autonomous, so it lets us move even faster.' },
			{ title: 'Strong ideas survive testing.', body: 'When many directions are explored, weak ideas reveal themselves quickly. The strongest hold up as they are tested, expanded and refined.' },
		],
	},
	roles: [
		{ title: 'Product designer', department: 'Design', href: '/careers' },
		{ title: 'Design engineer', department: 'Engineering', href: '/careers' },
	],
	footer,
}
export type AboutContent = typeof aboutContent
export const aboutSections = ['bets', 'team', 'process', 'openings'] as const
export type AboutSection = (typeof aboutSections)[number]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}
